<section class="content-header"><h1><i class="fa fa-percent"></i> Reporte de descuentos</h1></section><section class="content">
<div class="box box-warning no-print"><div class="box-body"><form method="get" class="form-inline"><label>Desde</label> <input type="date" name="desde" class="form-control" value="<?php echo html_escape($filtros['desde']);?>"> <label>Hasta</label> <input type="date" name="hasta" class="form-control" value="<?php echo html_escape($filtros['hasta']);?>"> <select name="usuario_id" class="form-control"><option value="0">Todos los usuarios</option><?php foreach($listas['usuarios'] as $u):?><option value="<?php echo $u['usuario_id'];?>" <?php echo $filtros['usuario_id']==$u['usuario_id']?'selected':'';?>><?php echo html_escape($u['usuario_nombre']);?></option><?php endforeach;?></select> <select name="ruta_id" class="form-control"><option value="0">Todas las rutas</option><?php foreach($listas['rutas'] as $r):?><option value="<?php echo $r['ruta_id'];?>" <?php echo $filtros['ruta_id']==$r['ruta_id']?'selected':'';?>><?php echo html_escape($r['ruta_nombre']);?></option><?php endforeach;?></select> <select name="tipodescuento_id" class="form-control"><option value="0">Todos los tipos</option><?php foreach($listas['tipos'] as $t):?><option value="<?php echo $t['tipodescuento_id'];?>" <?php echo $filtros['tipodescuento_id']==$t['tipodescuento_id']?'selected':'';?>><?php echo html_escape($t['tipodescuento_nombre']);?></option><?php endforeach;?></select> <button class="btn btn-warning"><i class="fa fa-search"></i> Generar</button></form></div></div>
<div class="box"><div class="box-header"><h3 class="box-title">Descuentos por usuario</h3><div class="pull-right no-print"><button onclick="window.print()" class="btn btn-default btn-sm"><i class="fa fa-print"></i> Imprimir</button> <a class="btn btn-success btn-sm" href="<?php echo site_url('reporte_descuentos/csv').'?'.http_build_query($filtros);?>"><i class="fa fa-file-excel-o"></i> Excel/CSV</a></div></div><div class="box-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Usuario</th><th class="text-right">Cantidad descuentos</th><th class="text-right">Importe descontado</th><th class="text-right">% sobre precio original</th></tr></thead><tbody><?php $tc=0;$ti=0;foreach($resumen as $r):$tc+=(int)$r['cantidad'];$ti+=(float)$r['importe'];?><tr><td><b><?php echo html_escape($r['usuario']);?></b></td><td class="text-right"><?php echo number_format($r['cantidad'],0,',','.');?></td><td class="text-right"><b>Bs <?php echo number_format($r['importe'],2,',','.');?></b></td><td class="text-right"><?php echo number_format($r['porcentaje'],1,',','.');?>%</td></tr><?php endforeach;?></tbody><tfoot><tr class="info"><th>TOTAL</th><th class="text-right"><?php echo number_format($tc,0,',','.');?></th><th class="text-right">Bs <?php echo number_format($ti,2,',','.');?></th><th></th></tr></tfoot></table></div></div></div>
<div class="box"><div class="box-header"><h3 class="box-title">Detalle para auditoría</h3></div><div class="box-body"><div class="table-responsive"><table class="table table-bordered table-condensed"><thead><tr><th>Fecha</th><th>Usuario</th><th>Tipo / ruta</th><th class="text-right">Original</th><th class="text-right">Descuento</th><th class="text-right">Final</th><th class="text-right">%</th><th>Motivo / autorización</th></tr></thead><tbody><?php foreach($detalle as $r):?><tr><td><?php echo html_escape($r['fecha']);?><br><small>Venta #<?php echo $r['venta_id'];?></small></td><td><b><?php echo html_escape($r['usuario']);?></b></td><td><?php echo html_escape($r['tipo']);?><br><small><?php echo html_escape($r['ruta']);?></small></td><td class="text-right">Bs <?php echo number_format($r['precio_original'],2,',','.');?></td><td class="text-right"><b>Bs <?php echo number_format($r['descuento'],2,',','.');?></b></td><td class="text-right">Bs <?php echo number_format($r['precio_final'],2,',','.');?></td><td class="text-right"><?php echo number_format($r['porcentaje'],1,',','.');?>%</td><td><?php echo html_escape($r['motivo']);?><?php if($r['autoriza']!=''):?><br><small>Autorizó: <?php echo html_escape($r['autoriza']);?></small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></section><style media="print">.no-print,.main-header,.main-sidebar,.content-header,.main-footer{display:none!important}.content-wrapper{margin-left:0!important}.content{padding:0!important}table{font-size:9px!important}</style>
